def safe_name(text):
    return (
        str(text)
        .replace(" ", "_")
        .replace("+", "plus")
        .replace("/", "_")
        .replace("\\", "_")
    )


def save_png_table(df, name, folder=TABLE_ROOT, title=None):
    """Save a publication-quality comparison table as a high-resolution PNG.

    The table is intentionally wide enough that long ensemble names and the
    final Training Time column are never clipped.  Text is wrapped in cells,
    and the first column receives extra width.
    """
    folder.mkdir(parents=True, exist_ok=True)
    png_path = folder / f"{name}.png"

    display_df = df.copy()
    for col in display_df.columns:
        if pd.api.types.is_numeric_dtype(display_df[col]):
            display_df[col] = display_df[col].round(4)
    display_df = display_df.fillna("N/A")

    # Wrap only the long text columns.  This prevents model/pair/trio names
    # from being cut off while keeping numerical columns compact.
    if "Model" in display_df.columns:
        display_df["Model"] = display_df["Model"].astype(str).apply(
            lambda x: "\n".join(textwrap.wrap(x, width=28, break_long_words=False))
        )

    n_rows, n_cols = display_df.shape

    # Explicit column widths.  The model column and final timing column are
    # deliberately wider than the other numeric columns.
    width_map = {
        "Model": 4.6,
        "Accuracy": 1.45,
        "Balanced Accuracy": 1.75,
        "Precision": 1.45,
        "Recall": 1.45,
        "Macro F1": 1.45,
        "Normal F1": 1.45,
        "AVP F1": 1.45,
        "Unknown F1": 1.45,
        "Trainable Parameters": 2.05,
        "Total Layers": 1.55,
        "Training Time (minutes)": 2.35,
    }

    fig_width = max(22, sum(width_map.get(c, 1.5) for c in display_df.columns) + 1.0)
    row_height = 0.62 if n_rows <= 6 else 0.55
    header_height = 0.92
    fig_height = max(4.2, header_height + (n_rows * row_height) + 1.25)

    fig, ax = plt.subplots(figsize=(fig_width, fig_height))
    ax.axis("off")

    if title:
        ax.set_title(title, fontsize=18, fontweight="bold", pad=20)

    col_widths = [width_map.get(c, 1.5) for c in display_df.columns]
    total = sum(col_widths)
    col_widths = [w / total for w in col_widths]

    table = ax.table(
        cellText=display_df.values,
        colLabels=display_df.columns,
        cellLoc="center",
        colLoc="center",
        colWidths=col_widths,
        loc="center",
        bbox=[0.005, 0.08, 0.99, 0.78],
    )

    table.auto_set_font_size(False)
    table.set_fontsize(10.5)

    # Professional header/body formatting.
    for (row, col), cell in table.get_celld().items():
        cell.set_edgecolor("#555555")
        cell.set_linewidth(0.65)
        cell.PAD = 0.018

        if row == 0:
            cell.set_text_props(weight="bold", fontsize=10.5, color="black")
            cell.set_facecolor("#E6E6E6")
            cell.set_height(header_height / fig_height)
        else:
            cell.set_facecolor("#F7F7F7" if row % 2 == 0 else "white")
            cell.set_height(row_height / fig_height)
            cell.get_text().set_verticalalignment("center")

            # Keep ensemble/model names left aligned and bold.
            if col == 0:
                cell.set_text_props(weight="bold", ha="left", fontsize=10.5)
            else:
                cell.set_text_props(ha="center", fontsize=10.2)

    # Make header labels wrap cleanly rather than overlap.
    for col, name_col in enumerate(display_df.columns):
        header = table[(0, col)]
        header.get_text().set_wrap(True)
        if name_col == "Training Time (minutes)":
            header.get_text().set_text("Training Time\n(minutes)")
        elif name_col == "Trainable Parameters":
            header.get_text().set_text("Trainable\nParameters")
        elif name_col == "Balanced Accuracy":
            header.get_text().set_text("Balanced\nAccuracy")

    # Add a little breathing room at the bottom for the title/table layout.
    plt.subplots_adjust(left=0.005, right=0.995, top=0.88, bottom=0.06)
    fig.savefig(
        png_path,
        dpi=300,
        bbox_inches="tight",
        pad_inches=0.12,
        facecolor="white",
    )
    plt.close(fig)

    print("Saved professional PNG table:", png_path)
    return png_path

def make_comparison_table(df, name_column, experiment_key, table_type):
    """Create the requested screenshot-style table using TEST-set metrics.

    Columns intentionally match the requested format:
    Model, Accuracy, Balanced Accuracy, Precision, Recall, Macro F1,
    Normal F1, AVP F1, Unknown F1, Trainable Parameters, Total Layers,
    Training Time (minutes).
    """
    metric_cols = [
        "Accuracy (%)",
        "Balanced Accuracy (%)",
        "Precision (%)",
        "Recall (%)",
        "Macro F1 (%)",
        "Normal F1 (%)",
        "AVP F1 (%)",
        "Unknown F1 (%)",
    ]

    output = pd.DataFrame()
    output["Model"] = df[name_column].astype(str)

    for metric in metric_cols:
        output[metric.replace(" (%)", "")] = df[f"Test {metric}"].values

    # Individual models store their elapsed time as "Training Time (min)",
    # while pairs/trios store the summed time as "Total Training Time (min)".
    # Use whichever column is present so all three table types render correctly.
    output["Trainable Parameters"] = df["Parameters"].values
    output["Total Layers"] = df["Layers"].values

    if "Training Time (min)" in df.columns:
        time_values = df["Training Time (min)"].values
    elif "Total Training Time (min)" in df.columns:
        time_values = df["Total Training Time (min)"].values
    else:
        # Defensive fallback: never crash the experiment just because a
        # timing column is unavailable. The table will show N/A instead.
        time_values = [np.nan] * len(df)

    output["Training Time (minutes)"] = time_values

    # Screenshot-like display names.
    output.columns = [
        "Model",
        "Accuracy",
        "Balanced Accuracy",
        "Precision",
        "Recall",
        "Macro F1",
        "Normal F1",
        "AVP F1",
        "Unknown F1",
        "Trainable Parameters",
        "Total Layers",
        "Training Time (minutes)",
    ]

    output = output.sort_values("Macro F1", ascending=False).reset_index(drop=True)

    safe_key = safe_name(experiment_key)
    safe_type = safe_name(table_type)
    path = save_png_table(
        output,
        f"{safe_key}_{safe_type}_comparison",
        title=f"{experiment_key} - {table_type} Model Comparison (Test Set)"
    )
    return output, path

def normalize_signals(X):
    X = np.asarray(X, dtype=np.float32)
    mean = np.mean(X, axis=1, keepdims=True)
    std = np.std(X, axis=1, keepdims=True)
    return ((X - mean) / (std + 1e-8)).astype(np.float32)


def get_consensus_label(record_path):
    """
    Read ARGO annotation_consensus using WFDB.

    Existing Colab code used P/A/U:
        P = physiological / Normal
        A = AVP
        U = Unknown
    """
    try:
        ann = wfdb.rdann(
            str(record_path),
            extension="annotation_consensus"
        )

        # First look at auxiliary annotation text.
        for note in getattr(ann, "aux_note", []):
            if note is None:
                continue
            note = str(note).strip()
            if len(note) >= 2 and note[0] == "(" and note[1] in {"P", "A", "U"}:
                return note[1]
            if note in {"P", "A", "U"}:
                return note

        # Then look at annotation symbols.
        for symbol in getattr(ann, "symbol", []):
            if symbol in {"P", "A", "U"}:
                return symbol

        return None

    except Exception as exc:
        print("Annotation error:", record_path, "|", exc)
        return None


def discover_records():
    rows = []

    patients = sorted(
        [p.name for p in DATA_ROOT.iterdir() if p.is_dir() and p.name.startswith("Pt")],
        key=lambda x: int(x.replace("Pt", ""))
    )

    print("\nPatients found:", patients)

    for patient in patients:
        patient_dir = DATA_ROOT / patient
        hea_files = sorted(patient_dir.glob("*.hea"))

        print(f"{patient}: {len(hea_files)} records")

        for hea in hea_files:
            record_path = hea.with_suffix("")
            label_symbol = get_consensus_label(record_path)

            if label_symbol in {"P", "A", "U"}:
                rows.append(
                    {
                        "patient": patient,
                        "record": str(record_path),
                        "label_symbol": label_symbol,
                    }
                )

    metadata = pd.DataFrame(rows)

    if metadata.empty:
        raise RuntimeError(
            "No labelled records were found. Check DATA_ROOT and WFDB annotations."
        )


    print("\nTotal labelled records:", len(metadata))
    print("\nOverall class distribution:")
    print(metadata["label_symbol"].value_counts())

    return metadata


def load_channels(record_path, channel_indices):
    record = wfdb.rdrecord(str(record_path))
    signal = np.asarray(record.p_signal, dtype=np.float32)

    if signal.ndim != 2:
        raise ValueError(f"Unexpected signal shape: {signal.shape}")

    if signal.shape[0] != WINDOW_SAMPLES:
        raise ValueError(
            f"Expected {WINDOW_SAMPLES} samples, got {signal.shape[0]} in {record_path}"
        )

    if max(channel_indices) >= signal.shape[1]:
        raise ValueError(
            f"Record has {signal.shape[1]} channels but requested {channel_indices}: {record_path}"
        )

    selected = signal[:, channel_indices]
    selected = np.nan_to_num(selected, nan=0.0, posinf=0.0, neginf=0.0)

    return selected.astype(np.float32)


def load_dataset(meta_df, channel_indices, symbol_to_id):
    X = []
    y = []
    groups = []
    records_used = []

    total = len(meta_df)

    for i, row in enumerate(meta_df.itertuples(index=False), start=1):
        try:
            signal = load_channels(row.record, channel_indices)

            X.append(signal)
            y.append(symbol_to_id[row.label_symbol])
            groups.append(row.patient)
            records_used.append(row.record)

        except Exception as exc:
            print("Skipping:", row.record, "|", exc)

        if i % 100 == 0 or i == total:
            print(f"  Loaded {i}/{total}")

    if not X:
        raise RuntimeError("No usable signals were loaded.")

    X = np.stack(X).astype(np.float32)
    y = np.asarray(y, dtype=np.int64)
    groups = np.asarray(groups)

    return X, y, groups, records_used


def make_class_weights(y):
    classes = np.unique(y)
    weights = compute_class_weight(
        class_weight="balanced",
        classes=classes,
        y=y
    )
    return {int(c): float(w) for c, w in zip(classes, weights)}


def metrics_dict(y_true, y_pred, class_names):
    """
    Calculate all requested classification metrics.

    Metrics:
        Accuracy
        Balanced Accuracy
        Precision
        Recall
        Macro F1
        Normal F1
        AVP F1
        Unknown F1
    """

    result = {
        "Accuracy (%)": accuracy_score(y_true, y_pred) * 100,

        "Balanced Accuracy (%)": (
            balanced_accuracy_score(y_true, y_pred) * 100
        ),

        "Precision (%)": (
            precision_score(
                y_true,
                y_pred,
                average="macro",
                zero_division=0
            ) * 100
        ),

        "Recall (%)": (
            recall_score(
                y_true,
                y_pred,
                average="macro",
                zero_division=0
            ) * 100
        ),

        "Macro F1 (%)": (
            f1_score(
                y_true,
                y_pred,
                average="macro",
                zero_division=0
            ) * 100
        ),

        # Default values.
        # They will be replaced below when the class exists.
        "Normal F1 (%)": np.nan,
        "AVP F1 (%)": np.nan,
        "Unknown F1 (%)": np.nan,
    }

    # Per-class F1
    per_class = f1_score(
        y_true,
        y_pred,
        labels=list(range(len(class_names))),
        average=None,
        zero_division=0
    )

    for i, class_name in enumerate(class_names):
        if i < len(per_class):

            if class_name == "Normal":
                result["Normal F1 (%)"] = per_class[i] * 100

            elif class_name == "AVP":
                result["AVP F1 (%)"] = per_class[i] * 100

            elif class_name == "Unknown":
                result["Unknown F1 (%)"] = per_class[i] * 100

    return result

def trainable_parameter_count(model):
    """Return only trainable parameters, matching the table heading."""
    return int(sum(np.prod(v.shape) for v in model.trainable_weights))


def add_metrics_to_row(
    row,
    prefix,
    metrics,
    parameter_count,
    layer_count=None
):
    """Add classification metrics plus model complexity information."""

    row[f"{prefix} Accuracy (%)"] = metrics["Accuracy (%)"]
    row[f"{prefix} Balanced Accuracy (%)"] = (
        metrics["Balanced Accuracy (%)"]
    )
    row[f"{prefix} Precision (%)"] = metrics["Precision (%)"]
    row[f"{prefix} Recall (%)"] = metrics["Recall (%)"]
    row[f"{prefix} Macro F1 (%)"] = metrics["Macro F1 (%)"]

    row[f"{prefix} Normal F1 (%)"] = metrics["Normal F1 (%)"]
    row[f"{prefix} AVP F1 (%)"] = metrics["AVP F1 (%)"]
    row[f"{prefix} Unknown F1 (%)"] = metrics["Unknown F1 (%)"]

    row["Layers"] = layer_count
    row["Parameters"] = parameter_count

    return row
