def build_1d_cnn(input_shape, num_classes):
    inputs = layers.Input(shape=input_shape)

    x = layers.Conv1D(32, 11, padding="same", activation="relu")(inputs)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(4)(x)

    x = layers.Conv1D(64, 9, padding="same", activation="relu")(x)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(4)(x)

    x = layers.Conv1D(128, 7, padding="same", activation="relu")(x)
    x = layers.BatchNormalization()(x)
    x = layers.MaxPooling1D(4)(x)

    x = layers.Conv1D(256, 5, padding="same", activation="relu")(x)
    x = layers.BatchNormalization()(x)

    x = layers.GlobalAveragePooling1D()(x)
    x = layers.Dropout(0.3)(x)

    outputs = layers.Dense(num_classes, activation="softmax")(x)

    return Model(inputs, outputs, name="1D_CNN")


def inception_block(x, filters=32):
    bottleneck = layers.Conv1D(
        filters, 1, padding="same", activation="relu"
    )(x)

    branch1 = layers.Conv1D(
        filters, 9, padding="same", activation="relu"
    )(bottleneck)

    branch2 = layers.Conv1D(
        filters, 19, padding="same", activation="relu"
    )(bottleneck)

    branch3 = layers.Conv1D(
        filters, 39, padding="same", activation="relu"
    )(bottleneck)

    branch4 = layers.MaxPooling1D(
        3, strides=1, padding="same"
    )(x)

    branch4 = layers.Conv1D(
        filters, 1, padding="same", activation="relu"
    )(branch4)

    x = layers.Concatenate()([
        branch1, branch2, branch3, branch4
    ])

    x = layers.BatchNormalization()(x)
    x = layers.ReLU()(x)

    return x


def build_inceptiontime(input_shape, num_classes):
    inputs = layers.Input(shape=input_shape)

    x = inception_block(inputs, 24)
    x = inception_block(x, 24)
    x = layers.MaxPooling1D(2)(x)

    x = inception_block(x, 32)
    x = inception_block(x, 32)

    x = layers.GlobalAveragePooling1D()(x)
    x = layers.Dropout(0.3)(x)

    outputs = layers.Dense(num_classes, activation="softmax")(x)

    return Model(inputs, outputs, name="InceptionTime")


class PositionalEmbedding(layers.Layer):
    def __init__(self, length, dim):
        super().__init__()
        self.length = length
        self.embedding = layers.Embedding(
            input_dim=length,
            output_dim=dim
        )

    def call(self, x):
        positions = tf.range(
            start=0,
            limit=self.length,
            delta=1
        )
        return x + self.embedding(positions)


def transformer_block(x, dim=64, heads=4, ff_dim=128, block_id=1):
    attention = layers.MultiHeadAttention(
        num_heads=heads,
        key_dim=dim // heads,
        name=f"transformer_mha_{block_id}"
    )(x, x)

    x = layers.LayerNormalization()(x + attention)

    ff = layers.Dense(ff_dim, activation="gelu")(x)
    ff = layers.Dropout(0.1)(ff)
    ff = layers.Dense(dim)(ff)

    x = layers.LayerNormalization()(x + ff)

    return x


def build_transformer(input_shape, num_classes):
    inputs = layers.Input(shape=input_shape)

    x = layers.Conv1D(
        64,
        9,
        strides=8,
        padding="same"
    )(inputs)

    token_length = int(np.ceil(input_shape[0] / 8))

    x = PositionalEmbedding(
        token_length,
        64
    )(x)

    x = transformer_block(x, 64, 4, 128, block_id=1)
    x = transformer_block(x, 64, 4, 128, block_id=2)
    x = transformer_block(x, 64, 4, 128, block_id=3)

    x = layers.GlobalAveragePooling1D()(x)
    x = layers.Dropout(0.3)(x)

    outputs = layers.Dense(num_classes, activation="softmax")(x)

    return Model(inputs, outputs, name="Transformer")


def convnext_block(x, dim, expansion=4):
    shortcut = x

    x = layers.DepthwiseConv1D(
        kernel_size=7,
        padding="same"
    )(x)

    x = layers.LayerNormalization()(x)

    x = layers.Conv1D(
        dim * expansion,
        1,
        activation="gelu"
    )(x)

    x = layers.Dropout(0.1)(x)

    x = layers.Conv1D(
        dim,
        1
    )(x)

    x = layers.Add()([shortcut, x])

    return x


def build_convnext1d(input_shape, num_classes):
    inputs = layers.Input(shape=input_shape)

    x = layers.Conv1D(
        64, 7, strides=4, padding="same"
    )(inputs)

    x = layers.LayerNormalization()(x)

    x = convnext_block(x, 64)
    x = convnext_block(x, 64)

    x = layers.Conv1D(
        128, 2, strides=2, padding="same"
    )(x)

    x = layers.LayerNormalization()(x)

    x = convnext_block(x, 128)
    x = convnext_block(x, 128)

    x = layers.Conv1D(
        256, 2, strides=2, padding="same"
    )(x)

    x = layers.LayerNormalization()(x)

    x = convnext_block(x, 256)
    x = convnext_block(x, 256)

    x = layers.GlobalAveragePooling1D()(x)
    x = layers.Dropout(0.3)(x)

    outputs = layers.Dense(num_classes, activation="softmax")(x)

    return Model(inputs, outputs, name="ConvNeXt1D")


MODEL_BUILDERS = {
    "1D CNN": build_1d_cnn,
    "InceptionTime": build_inceptiontime,
    "Transformer": build_transformer,
    "ConvNeXt1D": build_convnext1d,
}

# ============================================================
# 5. TRAINING
# ============================================================

class TestSetEvaluationCallback(tf.keras.callbacks.Callback):
    """Evaluate the held-out test set after every epoch for plotting only.

    Test results are never used for optimization, early stopping, or
    checkpoint selection. They are recorded only to produce the requested
    training/validation/testing curves.
    """
    def __init__(self, X_test, y_test):
        super().__init__()
        self.X_test = X_test
        self.y_test = y_test
        self.test_accuracy = []
        self.test_loss = []

    def on_epoch_end(self, epoch, logs=None):
        loss, accuracy = self.model.evaluate(
            self.X_test,
            self.y_test,
            batch_size=64,
            verbose=0
        )
        self.test_loss.append(float(loss))
        self.test_accuracy.append(float(accuracy))


def train_model(model_name, builder, X_train, y_train, X_val, y_val, X_test, y_test,
                input_shape, num_classes, class_weights, experiment_key):
    print("\n" + "=" * 90)
    print(f"TRAINING: {model_name} | {experiment_key}")
    print("=" * 90)

    tf.keras.backend.clear_session()

    model = builder(
        input_shape,
        num_classes
    )

    model.compile(
        optimizer=tf.keras.optimizers.Adam(
            learning_rate=0.001
        ),
        loss="sparse_categorical_crossentropy",
        metrics=["accuracy"]
    )

    model_dir = MODEL_ROOT / experiment_key
    model_dir.mkdir(parents=True, exist_ok=True)

    model_path = model_dir / f"{safe_name(model_name)}_best.keras"

    test_curve_callback = TestSetEvaluationCallback(X_test, y_test)

    callbacks = [
        test_curve_callback,
        tf.keras.callbacks.EarlyStopping(
            monitor="val_loss",
            patience=PATIENCE,
            restore_best_weights=True,
            verbose=1
        ),
        tf.keras.callbacks.ReduceLROnPlateau(
            monitor="val_loss",
            factor=0.5,
            patience=2,
            min_lr=1e-6,
            verbose=1
        ),
        tf.keras.callbacks.ModelCheckpoint(
            str(model_path),
            monitor="val_loss",
            save_best_only=True,
            verbose=1
        )
    ]

    start = time.time()

    history = model.fit(
        X_train,
        y_train,
        validation_data=(X_val, y_val),
        epochs=EPOCHS,
        batch_size=BATCH_SIZE,
        class_weight=class_weights,
        callbacks=callbacks,
        verbose=1
    )

    elapsed = time.time() - start

    # Restore the best checkpoint when available.
    if model_path.exists():
        try:
            model = tf.keras.models.load_model(
                model_path,
                custom_objects={
                    "PositionalEmbedding": PositionalEmbedding
                }
            )
        except Exception as exc:
            print("Could not reload checkpoint; using current model:", exc)

    history.history["test_accuracy"] = test_curve_callback.test_accuracy
    history.history["test_loss"] = test_curve_callback.test_loss

    return model, history, elapsed


# ============================================================
# 6. PREDICTION / ENSEMBLE
# ============================================================

def predict_model(model, X):
    probabilities = model.predict(
        X,
        batch_size=64,
        verbose=0
    )
    predictions = np.argmax(probabilities, axis=1)
    return probabilities, predictions


def average_probabilities(probability_list):
    return np.mean(
        np.stack(probability_list, axis=0),
        axis=0
    )


def evaluate_prediction(y_true, y_pred, class_names):
    return metrics_dict(
        y_true,
        y_pred,
        class_names
    )


def evaluate_ensemble(model_names, probability_cache, split_name,
                      y_true, class_names):
    probs = [
        probability_cache[name][split_name]
        for name in model_names
    ]

    avg_prob = average_probabilities(probs)
    pred = np.argmax(avg_prob, axis=1)

    metrics = evaluate_prediction(
        y_true,
        pred,
        class_names
    )

    return metrics, avg_prob, pred


