# Common settings for every accuracy/loss figure.
CURVE_FIGSIZE = (15, 9)
CURVE_LINEWIDTH = 4.0
CURVE_MARKERSIZE = 8
CURVE_TITLE_SIZE = 25
CURVE_LABEL_SIZE = 21
CURVE_TICK_SIZE = 18
CURVE_LEGEND_SIZE = 17


def _style_curve_axes(ax, title, xlabel, ylabel):
    """Apply the same large/bold publication style to curve plots."""
    ax.set_title(
        title,
        fontsize=CURVE_TITLE_SIZE,
        fontweight="bold",
        pad=18
    )
    ax.set_xlabel(
        xlabel,
        fontsize=CURVE_LABEL_SIZE,
        fontweight="bold",
        labelpad=12
    )
    ax.set_ylabel(
        ylabel,
        fontsize=CURVE_LABEL_SIZE,
        fontweight="bold",
        labelpad=12
    )

    ax.tick_params(
        axis="both",
        which="major",
        labelsize=CURVE_TICK_SIZE,
        width=2.2,
        length=7
    )

    for tick in ax.get_xticklabels() + ax.get_yticklabels():
        tick.set_fontweight("bold")

    ax.grid(
        True,
        which="major",
        alpha=0.30,
        linewidth=1.2
    )

    legend = ax.legend(
        loc="best",
        fontsize=CURVE_LEGEND_SIZE,
        frameon=True,
        framealpha=0.95,
        borderpad=0.8
    )

    for text in legend.get_texts():
        text.set_fontweight("bold")

    # Make the plot border stronger and easier to see.
    for spine in ax.spines.values():
        spine.set_linewidth(2.0)


def _save_curve(fig, path):
    """Save a high-resolution figure without clipping any text."""
    fig.tight_layout(pad=2.0)
    fig.savefig(
        path,
        dpi=400,
        bbox_inches="tight",
        pad_inches=0.25,
        facecolor="white"
    )
    plt.close(fig)


def plot_single_history(history, model_name, experiment_key, out_dir):
    """
    Save large, bold Training/Validation/Testing accuracy and loss curves
    for an individual model.
    """
    out_dir.mkdir(parents=True, exist_ok=True)

    epochs = np.arange(
        1,
        len(history.history["accuracy"]) + 1
    )

    # --------------------------------------------------------
    # Accuracy
    # --------------------------------------------------------
    fig, ax = plt.subplots(figsize=CURVE_FIGSIZE)

    ax.plot(
        epochs,
        history.history["accuracy"],
        linewidth=CURVE_LINEWIDTH,
        marker="o",
        markersize=CURVE_MARKERSIZE,
        label="Training Accuracy"
    )

    ax.plot(
        epochs,
        history.history["val_accuracy"],
        linewidth=CURVE_LINEWIDTH,
        linestyle="--",
        marker="s",
        markersize=CURVE_MARKERSIZE,
        label="Validation Accuracy"
    )

    if "test_accuracy" in history.history:
        ax.plot(
            epochs[:len(history.history["test_accuracy"])],
            history.history["test_accuracy"],
            linewidth=CURVE_LINEWIDTH,
            linestyle=":",
            marker="^",
            markersize=CURVE_MARKERSIZE,
            label="Testing Accuracy"
        )

    ax.set_xlim(1, max(1, len(epochs)))
    ax.set_ylim(0, 1.05)

    _style_curve_axes(
        ax,
        f"{experiment_key} - {model_name} Accuracy",
        "Epoch",
        "Accuracy"
    )

    _save_curve(
        fig,
        out_dir / f"{safe_name(model_name)}_accuracy.png"
    )

    # --------------------------------------------------------
    # Loss
    # --------------------------------------------------------
    fig, ax = plt.subplots(figsize=CURVE_FIGSIZE)

    ax.plot(
        epochs,
        history.history["loss"],
        linewidth=CURVE_LINEWIDTH,
        marker="o",
        markersize=CURVE_MARKERSIZE,
        label="Training Loss"
    )

    ax.plot(
        epochs,
        history.history["val_loss"],
        linewidth=CURVE_LINEWIDTH,
        linestyle="--",
        marker="s",
        markersize=CURVE_MARKERSIZE,
        label="Validation Loss"
    )

    if "test_loss" in history.history:
        ax.plot(
            epochs[:len(history.history["test_loss"])],
            history.history["test_loss"],
            linewidth=CURVE_LINEWIDTH,
            linestyle=":",
            marker="^",
            markersize=CURVE_MARKERSIZE,
            label="Testing Loss"
        )

    ax.set_xlim(1, max(1, len(epochs)))

    # Start loss axis at zero when possible.
    all_losses = list(history.history["loss"]) + list(history.history["val_loss"])
    if "test_loss" in history.history:
        all_losses += list(history.history["test_loss"])

    max_loss = max(all_losses) if all_losses else 1.0
    ax.set_ylim(0, max_loss * 1.12)

    _style_curve_axes(
        ax,
        f"{experiment_key} - {model_name} Loss",
        "Epoch",
        "Loss"
    )

    _save_curve(
        fig,
        out_dir / f"{safe_name(model_name)}_loss.png"
    )


def plot_best_ensemble_curves(
    best_name,
    best_model_names,
    histories,
    experiment_key,
    out_dir
):
    """Plot large/bold Training + Validation + Testing curves.

    For a pair/trio, curves are the mean of the component-model curves.
    This remains consistent with the existing probability-averaging
    ensemble approach.
    """
    out_dir.mkdir(parents=True, exist_ok=True)

    hist_list = [histories[name].history for name in best_model_names]

    # Use the common number of epochs available for all selected models.
    n = min(len(h["accuracy"]) for h in hist_list)
    epochs = np.arange(1, n + 1)

    def mean_key(key):
        available = []
        for h in hist_list:
            if key in h:
                available.append(np.asarray(h[key][:n], dtype=float))

        if not available:
            return None

        common_n = min(len(v) for v in available)
        return np.mean(
            [v[:common_n] for v in available],
            axis=0
        )

    train_acc = mean_key("accuracy")
    val_acc = mean_key("val_accuracy")
    test_acc = mean_key("test_accuracy")

    train_loss = mean_key("loss")
    val_loss = mean_key("val_loss")
    test_loss = mean_key("test_loss")

    base = safe_name(best_name)

    # --------------------------------------------------------
    # Accuracy curve
    # --------------------------------------------------------
    fig, ax = plt.subplots(figsize=CURVE_FIGSIZE)

    ax.plot(
        epochs[:len(train_acc)],
        train_acc,
        linewidth=CURVE_LINEWIDTH,
        marker="o",
        markersize=CURVE_MARKERSIZE,
        label="Training Accuracy"
    )

    ax.plot(
        epochs[:len(val_acc)],
        val_acc,
        linewidth=CURVE_LINEWIDTH,
        linestyle="--",
        marker="s",
        markersize=CURVE_MARKERSIZE,
        label="Validation Accuracy"
    )

    if test_acc is not None:
        ax.plot(
            epochs[:len(test_acc)],
            test_acc,
            linewidth=CURVE_LINEWIDTH,
            linestyle=":",
            marker="^",
            markersize=CURVE_MARKERSIZE,
            label="Testing Accuracy"
        )

    ax.set_xlim(1, max(1, len(epochs)))
    ax.set_ylim(0, 1.05)

    _style_curve_axes(
        ax,
        f"{experiment_key} - {best_name} Accuracy",
        "Epoch",
        "Accuracy"
    )

    _save_curve(
        fig,
        out_dir / f"{base}_accuracy_curve.png"
    )

    # --------------------------------------------------------
    # Loss curve
    # --------------------------------------------------------
    fig, ax = plt.subplots(figsize=CURVE_FIGSIZE)

    ax.plot(
        epochs[:len(train_loss)],
        train_loss,
        linewidth=CURVE_LINEWIDTH,
        marker="o",
        markersize=CURVE_MARKERSIZE,
        label="Training Loss"
    )

    ax.plot(
        epochs[:len(val_loss)],
        val_loss,
        linewidth=CURVE_LINEWIDTH,
        linestyle="--",
        marker="s",
        markersize=CURVE_MARKERSIZE,
        label="Validation Loss"
    )

    if test_loss is not None:
        ax.plot(
            epochs[:len(test_loss)],
            test_loss,
            linewidth=CURVE_LINEWIDTH,
            linestyle=":",
            marker="^",
            markersize=CURVE_MARKERSIZE,
            label="Testing Loss"
        )

    all_losses = []
    for values in (train_loss, val_loss, test_loss):
        if values is not None:
            all_losses.extend(values.tolist())

    max_loss = max(all_losses) if all_losses else 1.0
    ax.set_xlim(1, max(1, len(epochs)))
    ax.set_ylim(0, max_loss * 1.12)

    _style_curve_axes(
        ax,
        f"{experiment_key} - {best_name} Loss",
        "Epoch",
        "Loss"
    )

    _save_curve(
        fig,
        out_dir / f"{base}_loss_curve.png"
    )


