# 8. ATTENTION MATRIX VISUALIZATION
# ============================================================

def plot_transformer_attention_concatenated(
    model,
    X_sample,
    experiment_key,
    out_dir,
    max_samples=1
):
    """
    Extract the first Transformer self-attention block and create a
    single attention matrix by concatenating the four attention-head
    matrices horizontally.

    The four heads are kept separate in the concatenated matrix:
        [Head 1 | Head 2 | Head 3 | Head 4]

    This is an interpretability visualization only; it does not change
    the trained Transformer architecture or its predictions.
    """
    if model.name != "Transformer":
        return None

    try:
        mha = model.get_layer("transformer_mha_1")
    except Exception as exc:
        print("Attention layer not found:", exc)
        return None

    try:
        node_inputs = mha.input
        if isinstance(node_inputs, (list, tuple)):
            query = node_inputs[0]
            value = node_inputs[1] if len(node_inputs) > 1 else node_inputs[0]
        else:
            query = node_inputs
            value = node_inputs

        _, attention_scores = mha(
            query,
            value,
            return_attention_scores=True
        )

        attention_model = Model(
            inputs=model.input,
            outputs=attention_scores,
            name="TransformerAttentionExtractor"
        )

        scores = attention_model.predict(
            X_sample[:max_samples],
            batch_size=1,
            verbose=0
        )

        # scores shape:
        #   (batch, heads, query_tokens, key_tokens)
        sample_scores = np.asarray(scores[0], dtype=np.float32)

        if sample_scores.ndim != 3:
            raise ValueError(
                f"Unexpected attention score shape: {sample_scores.shape}"
            )

        # Concatenate the four heads horizontally:
        # (tokens, tokens * heads)
        concatenated = np.concatenate(
            [sample_scores[h] for h in range(sample_scores.shape[0])],
            axis=1
        )

        out_dir.mkdir(parents=True, exist_ok=True)

        fig_width = max(12, concatenated.shape[1] / 8)
        fig_height = max(7, concatenated.shape[0] / 8)

        fig = plt.figure(figsize=(fig_width, fig_height))
        ax = fig.add_subplot(111)

        image = ax.imshow(
            concatenated,
            aspect="auto",
            cmap="viridis",
            interpolation="nearest"
        )

        ax.set_xlabel(
            "Key tokens (concatenated attention heads: "
            + " | ".join(
                f"Head {i + 1}"
                for i in range(sample_scores.shape[0])
            )
            + ")"
        )
        ax.set_ylabel("Query tokens")
        ax.set_title(
            f"{experiment_key} - Transformer Attention Matrix\n"
            f"First self-attention block, heads concatenated"
        )

        # Head boundaries
        token_count = sample_scores.shape[1]
        for h in range(1, sample_scores.shape[0]):
            ax.axvline(
                h * token_count - 0.5,
                linewidth=1.2,
                linestyle="--"
            )

        fig.colorbar(image, ax=ax, label="Attention score")
        plt.tight_layout()

        path = out_dir / "Transformer_Attention_Matrix_Concatenated.png"
        plt.savefig(path, dpi=300, bbox_inches="tight")
        plt.close(fig)

        print("Saved attention matrix PNG:", path)

        return path

    except Exception as exc:
        print("Could not generate Transformer attention matrix:", exc)
        return None


