# 9. RUN ONE EXPERIMENT
# ============================================================

def run_experiment(
    metadata,
    experiment_name,
    channel_indices,
    class_mode
):
    class_info = CLASS_CONFIGS[class_mode]
    label_symbols = class_info["label_symbols"]
    class_names = class_info["class_names"]

    experiment_key = (
        f"{experiment_name}__{class_mode}"
    )

    print("\n\n")
    print("#" * 100)
    print("EXPERIMENT:", experiment_key)
    print("Channels :", channel_indices)
    print("Classes  :", class_names)
    print("#" * 100)

    out_fig = FIG_ROOT / experiment_key
    out_fig.mkdir(parents=True, exist_ok=True)

    # Filter records for this class setup.
    exp_meta = metadata[
        metadata["label_symbol"].isin(label_symbols)
    ].copy()

    symbol_to_id = {
        symbol: idx
        for idx, symbol in enumerate(label_symbols)
    }

    exp_meta["label"] = exp_meta["label_symbol"].map(symbol_to_id)

    train_meta = exp_meta[
        exp_meta["patient"].isin(TRAIN_PATIENTS)
    ].reset_index(drop=True)

    val_meta = exp_meta[
        exp_meta["patient"].isin(VAL_PATIENTS)
    ].reset_index(drop=True)

    test_meta = exp_meta[
        exp_meta["patient"].isin(TEST_PATIENTS)
    ].reset_index(drop=True)

    print("\nRecords:")
    print("  Train:", len(train_meta))
    print("  Val  :", len(val_meta))
    print("  Test :", len(test_meta))

    if train_meta.empty or val_meta.empty or test_meta.empty:
        print("WARNING: One split is empty. Experiment skipped.")
        return None

    # Load signals.
    print("\nLoading training signals...")
    X_train, y_train, group_train, train_records = load_dataset(
        train_meta,
        channel_indices,
        symbol_to_id
    )

    print("\nLoading validation signals...")
    X_val, y_val, group_val, val_records = load_dataset(
        val_meta,
        channel_indices,
        symbol_to_id
    )

    print("\nLoading testing signals...")
    X_test, y_test, group_test, test_records = load_dataset(
        test_meta,
        channel_indices,
        symbol_to_id
    )

    print("\nRaw shapes:")
    print("  X_train:", X_train.shape)
    print("  X_val  :", X_val.shape)
    print("  X_test :", X_test.shape)

    # Normalize each EGM independently, matching the current Colab approach.
    X_train = normalize_signals(X_train)
    X_val = normalize_signals(X_val)
    X_test = normalize_signals(X_test)

    input_shape = X_train.shape[1:]
    num_classes = len(class_names)

    class_weights = make_class_weights(y_train)

    print("\nClass weights:", class_weights)

    print("\nTraining class distribution:")
    print(pd.Series(y_train).value_counts().sort_index())

    # Save experiment data metadata.
    split_summary = pd.DataFrame(
        {
            "Split": ["Train", "Validation", "Test"],
            "Samples": [
                len(y_train),
                len(y_val),
                len(y_test)
            ],
        }
    )

    # --------------------------------------------------------
    # Train all four models
    # --------------------------------------------------------

    trained_models = {}
    histories = {}
    training_times = {}

    individual_rows = []

    for model_name, builder in MODEL_BUILDERS.items():
        model, history, elapsed = train_model(
            model_name,
            builder,
            X_train,
            y_train,
            X_val,
            y_val,
            X_test,
            y_test,
            input_shape,
            num_classes,
            class_weights,
            experiment_key
        )

        trained_models[model_name] = model
        histories[model_name] = history
        training_times[model_name] = elapsed

        split_metrics = {}

        for split_name, X, y in [
            ("Train", X_train, y_train),
            ("Validation", X_val, y_val),
            ("Test", X_test, y_test),
        ]:
            probs, pred = predict_model(model, X)
            split_metrics[split_name] = metrics_dict(
                y,
                pred,
                class_names
            )

        row = {
            "Experiment": experiment_key,
            "Model": model_name,
        }

        add_metrics_to_row(
            row, "Train", split_metrics["Train"],
            trainable_parameter_count(model), len(model.layers)
        )
        add_metrics_to_row(
            row, "Validation", split_metrics["Validation"],
            trainable_parameter_count(model), len(model.layers)
        )
        add_metrics_to_row(
            row, "Test", split_metrics["Test"],
            trainable_parameter_count(model), len(model.layers)
        )

        row["Training Time (min)"] = elapsed / 60.0
        individual_rows.append(row)

    # --------------------------------------------------------
    # Transformer attention matrix using concatenation
    # --------------------------------------------------------
    # Generate this only for the Transformer and use the first test
    # sample for a deterministic interpretability figure.
    if "Transformer" in trained_models and len(X_test) > 0:
        plot_transformer_attention_concatenated(
            trained_models["Transformer"],
            X_test,
            experiment_key,
            out_fig
        )

    individual_df = pd.DataFrame(individual_rows)
    individual_df = individual_df.sort_values(
        "Validation Macro F1 (%)",
        ascending=False
    ).reset_index(drop=True)

    individual_table, _ = make_comparison_table(
        individual_df,
        "Model",
        experiment_key,
        "Individual"
    )

    print("\nINDIVIDUAL MODEL COMPARISON - TEST SET")
    print(individual_table.round(2).to_string(index=False))

    probability_cache = {
        model_name: {} for model_name in MODEL_BUILDERS
    }
    prediction_cache = {
        model_name: {} for model_name in MODEL_BUILDERS
    }

    split_data = {
        "Train": (X_train, y_train),
        "Validation": (X_val, y_val),
        "Test": (X_test, y_test),
    }

    for model_name, model in trained_models.items():
        for split_name, (X, y) in split_data.items():
            probs, pred = predict_model(model, X)
            probability_cache[model_name][split_name] = probs
            prediction_cache[model_name][split_name] = pred

    # All 2-model combinations
    pair_rows = []

    for pair in combinations(MODEL_BUILDERS.keys(), 2):
        names = list(pair)

        train_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Train", y_train, class_names
        )
        val_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Validation", y_val, class_names
        )
        test_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Test", y_test, class_names
        )

        pair_row = {
            "Experiment": experiment_key,
            "Model Pair": " + ".join(pair),
        }

        pair_parameters = sum(
            trainable_parameter_count(trained_models[m]) for m in pair
        )

        pair_layers = sum(len(trained_models[m].layers) for m in pair)

        add_metrics_to_row(
            pair_row, "Train", train_metrics, pair_parameters, pair_layers
        )
        add_metrics_to_row(
            pair_row, "Validation", val_metrics, pair_parameters, pair_layers
        )
        add_metrics_to_row(
            pair_row, "Test", test_metrics, pair_parameters, pair_layers
        )

        pair_row["Total Training Time (min)"] = (
            sum(training_times[m] for m in pair) / 60.0
        )
        pair_rows.append(pair_row)

    pair_df = pd.DataFrame(pair_rows).sort_values(
        "Validation Macro F1 (%)",
        ascending=False
    ).reset_index(drop=True)

    pair_table, _ = make_comparison_table(
        pair_df,
        "Model Pair",
        experiment_key,
        "2_Model_Pair"
    )

    print("\n2-MODEL PAIR COMPARISON - TEST SET")
    print(pair_table.round(2).to_string(index=False))

    # All 3-model combinations
    trio_rows = []

    for trio in combinations(MODEL_BUILDERS.keys(), 3):
        names = list(trio)

        train_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Train", y_train, class_names
        )
        val_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Validation", y_val, class_names
        )
        test_metrics, _, _ = evaluate_ensemble(
            names, probability_cache, "Test", y_test, class_names
        )

        trio_row = {
            "Experiment": experiment_key,
            "Model Trio": " + ".join(trio),
        }

        trio_parameters = sum(
            trainable_parameter_count(trained_models[m]) for m in trio
        )

        trio_layers = sum(len(trained_models[m].layers) for m in trio)

        add_metrics_to_row(
            trio_row, "Train", train_metrics, trio_parameters, trio_layers
        )
        add_metrics_to_row(
            trio_row, "Validation", val_metrics, trio_parameters, trio_layers
        )
        add_metrics_to_row(
            trio_row, "Test", test_metrics, trio_parameters, trio_layers
        )

        trio_row["Total Training Time (min)"] = (
            sum(training_times[m] for m in trio) / 60.0
        )
        trio_rows.append(trio_row)

    trio_df = pd.DataFrame(trio_rows).sort_values(
        "Validation Macro F1 (%)",
        ascending=False
    ).reset_index(drop=True)

    trio_table, _ = make_comparison_table(
        trio_df,
        "Model Trio",
        experiment_key,
        "3_Model_Trio"
    )

    # At this point exactly three PNG comparison tables have been generated
    # for this class configuration: Individual, 2-Model Pair, 3-Model Trio.

    print("\n3-MODEL TRIO COMPARISON - TEST SET")
    print(trio_table.round(2).to_string(index=False))

    # Select best individual, pair, and trio using validation Macro F1.
    best_single = individual_df.iloc[0]["Model"]
    best_pair_text = pair_df.iloc[0]["Model Pair"]
    best_trio_text = trio_df.iloc[0]["Model Trio"]

    best_pair = [x.strip() for x in best_pair_text.split("+")]
    best_trio = [x.strip() for x in best_trio_text.split("+")]

    selections = [
        ("Best Individual", [best_single]),
        ("Best 2-Model Pair", best_pair),
        ("Best 3-Model Trio", best_trio),
    ]

    best_rows = []

    for selection_name, names in selections:
        train_metrics, train_prob, train_pred = evaluate_ensemble(
            names, probability_cache, "Train", y_train, class_names
        )
        val_metrics, val_prob, val_pred = evaluate_ensemble(
            names, probability_cache, "Validation", y_val, class_names
        )
        test_metrics, test_prob, test_pred = evaluate_ensemble(
            names, probability_cache, "Test", y_test, class_names
        )

        best_row = {
            "Experiment": experiment_key,
            "Selection": selection_name,
            "Models": " + ".join(names),
        }

        parameter_count = sum(
            trainable_parameter_count(trained_models[m]) for m in names
        )

        layer_count = sum(len(trained_models[m].layers) for m in names)

        add_metrics_to_row(
            best_row, "Train", train_metrics, parameter_count, layer_count
        )
        add_metrics_to_row(
            best_row, "Validation", val_metrics, parameter_count, layer_count
        )
        add_metrics_to_row(
            best_row, "Test", test_metrics, parameter_count, layer_count
        )

        best_rows.append(best_row)

        plot_confusion(
            y_test,
            test_pred,
            class_names,
            f"{experiment_key} - {selection_name}",
            out_fig / f"{safe_name(selection_name)}_confusion_matrix.png"
        )

    best_summary = pd.DataFrame(best_rows)

    plot_best_ensemble_curves(
        "Best Individual - " + best_single,
        [best_single],
        histories,
        experiment_key,
        out_fig
    )

    plot_best_ensemble_curves(
        "Best 2-Model Pair - " + best_pair_text,
        best_pair,
        histories,
        experiment_key,
        out_fig
    )

    plot_best_ensemble_curves(
        "Best 3-Model Trio - " + best_trio_text,
        best_trio,
        histories,
        experiment_key,
        out_fig
    )

    plot_best_train_val_test_accuracy(
        best_summary,
        experiment_key,
        out_fig
    )

    print("\n" + "=" * 100)
    print("BEST RESULTS:", experiment_key)
    print("=" * 100)
    print("Best individual:", best_single)
    print("Best 2-model   :", best_pair_text)
    print("Best 3-model   :", best_trio_text)
    print("\nBest-model comparison:")
    print(best_summary.round(2).to_string(index=False))

    return {
        "Experiment": experiment_key,
        "Best Individual": best_single,
        "Best Individual Test Accuracy (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best Individual",
                "Test Accuracy (%)"
            ].iloc[0]),
        "Best Individual Test Macro F1 (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best Individual",
                "Test Macro F1 (%)"
            ].iloc[0]),
        "Best 2-Model Pair": best_pair_text,
        "Best 2-Model Test Accuracy (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best 2-Model Pair",
                "Test Accuracy (%)"
            ].iloc[0]),
        "Best 2-Model Test Macro F1 (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best 2-Model Pair",
                "Test Macro F1 (%)"
            ].iloc[0]),
        "Best 3-Model Trio": best_trio_text,
        "Best 3-Model Test Accuracy (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best 3-Model Trio",
                "Test Accuracy (%)"
            ].iloc[0]),
        "Best 3-Model Test Macro F1 (%)":
            float(best_summary.loc[
                best_summary["Selection"] == "Best 3-Model Trio",
                "Test Macro F1 (%)"
            ].iloc[0]),
    }
# ============================================================
# 9. MAIN
# ============================================================

def main():
    metadata = discover_records()

    # Save class distribution.
    class_dist = (
        metadata["label_symbol"]
        .value_counts()
        .rename_axis("Label")
        .reset_index(name="Count")
    )
    all_best = []

    total_experiments = len(EXPERIMENTS) * len(CLASS_CONFIGS)  # 2 bipolar class configurations

    counter = 0

    for experiment_name, channels in EXPERIMENTS.items():
        for class_mode in CLASS_CONFIGS.keys():
            counter += 1

            print("\n")
            print("=" * 100)
            print(
                f"RUNNING EXPERIMENT {counter}/{total_experiments}: "
                f"{experiment_name} | {class_mode}"
            )
            print("=" * 100)

            summary = run_experiment(
                metadata,
                experiment_name,
                channels,
                class_mode
            )

            if summary is not None:
                all_best.append(summary)

    # Global summary.
    if all_best:
        global_df = pd.DataFrame(all_best)
        global_df = global_df.sort_values(
            "Best Individual Test Accuracy (%)",
            ascending=False
        ).reset_index(drop=True)

        print("\n\n" + "#" * 110)
        print("GLOBAL BEST RESULTS - BIPOLAR: 2-CLASS + 3-CLASS")
        print("#" * 110)
        print(global_df.round(2).to_string(index=False))

        # Overall best individual / pair / trio based on TEST accuracy
        # is reported only after the two bipolar experiments have completed.
        best_ind_row = global_df.iloc[
            global_df["Best Individual Test Accuracy (%)"].idxmax()
        ]

        best_pair_row = global_df.iloc[
            global_df["Best 2-Model Test Accuracy (%)"].idxmax()
        ]

        best_trio_row = global_df.iloc[
            global_df["Best 3-Model Test Accuracy (%)"].idxmax()
        ]

        overall = pd.DataFrame(
            [
                {
                    "Category": "Overall Best Individual",
                    "Experiment": best_ind_row["Experiment"],
                    "Models": best_ind_row["Best Individual"],
                    "Test Accuracy (%)":
                        best_ind_row["Best Individual Test Accuracy (%)"],
                    "Test Macro F1 (%)":
                        best_ind_row["Best Individual Test Macro F1 (%)"],
                },
                {
                    "Category": "Overall Best 2-Model Pair",
                    "Experiment": best_pair_row["Experiment"],
                    "Models": best_pair_row["Best 2-Model Pair"],
                    "Test Accuracy (%)":
                        best_pair_row["Best 2-Model Test Accuracy (%)"],
                    "Test Macro F1 (%)":
                        best_pair_row["Best 2-Model Test Macro F1 (%)"],
                },
                {
                    "Category": "Overall Best 3-Model Trio",
                    "Experiment": best_trio_row["Experiment"],
                    "Models": best_trio_row["Best 3-Model Trio"],
                    "Test Accuracy (%)":
                        best_trio_row["Best 3-Model Test Accuracy (%)"],
                    "Test Macro F1 (%)":
                        best_trio_row["Best 3-Model Test Macro F1 (%)"],
                },
            ]
        )

        print("\nOVERALL BEST:")
        print(overall.round(2).to_string(index=False))

    print("\n" + "=" * 100)
    print("ALL ARGO EXPERIMENTS COMPLETED")
    print("=" * 100)
    print("Results:", RESULT_ROOT)
    print("Tables :", TABLE_ROOT)
    print("Figures:", FIG_ROOT)
    print("Models :", MODEL_ROOT)


if __name__ == "__main__":
    main()